25	import org.apache.accumulo.core.client.ConditionalWriter.Result;
26	import org.apache.accumulo.core.client.ConditionalWriter.Status;
27	import org.apache.accumulo.core.data.ConditionalMutation;
28	
29	import com.google.common.base.Preconditions;
30	import com.google.common.collect.Streams;
31	
32	public interface ConditionalWriterInterceptor {
33	
34	  default Iterator<ConditionalMutation> beforeWrite(Iterator<ConditionalMutation> mutations) {
35	    return mutations;
36	  }
37	
38	  default Iterator<Result> afterWrite(Iterator<Result> results) {
39	    return results;
40	  }
41	
42	  default ConditionalMutation beforeWrite(ConditionalMutation mutation) {
43	    return mutation;
44	  }
45	
46	  default Result afterWrite(Result result) {
47	    return result;
48	  }
49	
50	  default void beforeClose() {
51	
52	  }
53	
54	  default void afterClose() {
55	
56	  }
57	
58	  static ConditionalWriterInterceptor withStatus(Status replaced, int times) {
59	    return withStatus(null, replaced, times);
60	  }
61	
62	  static ConditionalWriterInterceptor withStatus(Status firstExpected, Status replaced, int times) {
63	    final AtomicInteger count = new AtomicInteger();
64	    return new ConditionalWriterInterceptor() {
65	      @Override
66	      public Iterator<Result> afterWrite(Iterator<Result> results) {
67	        if (count.getAndIncrement() < times) {
68	          // For the first run only, make sure each state matches firstExpected if not null
69	          // for other runs don't check since we are changing state so future runs may not match
70	          return Streams.stream(results).map(r -> {
71	            try {
72	              Preconditions
73	                  .checkState(times > 1 || firstExpected == null || r.getStatus() == firstExpected);
74	            } catch (IllegalStateException e) {
75	              throw e;
76	            } catch (Exception e) {
77	              throw new IllegalStateException(e);
78	            }
79	            return new Result(replaced, r.getMutation(), r.getTabletServer());
80	          }).collect(Collectors.toList()).iterator();
81	        }
82	        return results;
83	      }
84	    };
85	  }
86	}
