26	class ConditionalWriterDelegator implements ConditionalWriter {
27	  private final ConditionalWriter delegate;
28	  private final ConditionalWriterInterceptor interceptor;
29	
30	  public ConditionalWriterDelegator(ConditionalWriter delegate,
31	      ConditionalWriterInterceptor interceptor) {
32	    this.delegate = delegate;
33	    this.interceptor = interceptor;
34	  }
35	
36	  @Override
37	  public Iterator<Result> write(Iterator<ConditionalMutation> mutations) {
38	    mutations = interceptor.beforeWrite(mutations);
39	    return interceptor.afterWrite(delegate.write(mutations));
40	  }
41	
42	  @Override
43	  public Result write(ConditionalMutation mutation) {
44	    mutation = interceptor.beforeWrite(mutation);
45	    return interceptor.afterWrite(delegate.write(mutation));
46	  }
47	
48	  @Override
49	  public void close() {
50	    interceptor.beforeClose();
51	    delegate.close();
52	    interceptor.afterClose();
53	  }
54	}
