52	    /**
53	     * If this method throws an exception, then its possible the mutation is still being actively
54	     * processed. Therefore if code chooses to continue after seeing an exception it should take
55	     * this into consideration.
56	     *
57	     * @return status of a conditional mutation
58	     */
59	
60	    public Status getStatus() throws AccumuloException, AccumuloSecurityException {
61	      if (status == null) {
62	        if (exception instanceof AccumuloException) {
63	          throw new AccumuloException(exception);
64	        }
65	        if (exception instanceof AccumuloSecurityException) {
66	          AccumuloSecurityException ase = (AccumuloSecurityException) exception;
67	          throw new AccumuloSecurityException(ase.getUser(),
68	              SecurityErrorCode.valueOf(ase.getSecurityErrorCode().name()), ase.getTableInfo(),
69	              ase);
70	        } else {
71	          throw new AccumuloException(exception);
72	        }
73	      }
74	
75	      return status;
76	    }
